WITH windows AS (SELECT 0 AS sample, 17327 AS pid, 9713640000000 AS start_ns, 9715473795166 AS end_ns UNION ALL SELECT 1 AS sample, 17327 AS pid, 9716390000000 AS start_ns, 9718049206334 AS end_ns UNION ALL SELECT 2 AS sample, 17327 AS pid, 9718910000000 AS start_ns, 9720559286582 AS end_ns UNION ALL SELECT 3 AS sample, 17327 AS pid, 9721370000000 AS start_ns, 9723034377584 AS end_ns UNION ALL SELECT 4 AS sample, 17327 AS pid, 9723950000000 AS start_ns, 9725631806583 AS end_ns UNION ALL SELECT 5 AS sample, 17327 AS pid, 9726460000000 AS start_ns, 9728113650999 AS end_ns UNION ALL SELECT 6 AS sample, 17327 AS pid, 9728860000000 AS start_ns, 9730508096375 AS end_ns UNION ALL SELECT 7 AS sample, 17327 AS pid, 9731310000000 AS start_ns, 9732971766624 AS end_ns UNION ALL SELECT 8 AS sample, 17327 AS pid, 9733810000000 AS start_ns, 9735457144833 AS end_ns UNION ALL SELECT 9 AS sample, 17327 AS pid, 9736410000000 AS start_ns, 9738063927457 AS end_ns UNION ALL SELECT 10 AS sample, 17327 AS pid, 9738870000000 AS start_ns, 9740563035707 AS end_ns UNION ALL SELECT 11 AS sample, 17327 AS pid, 9741330000000 AS start_ns, 9742980043041 AS end_ns UNION ALL SELECT 12 AS sample, 17327 AS pid, 9743700000000 AS start_ns, 9745348278375 AS end_ns UNION ALL SELECT 13 AS sample, 17327 AS pid, 9746470000000 AS start_ns, 9748145757666 AS end_ns UNION ALL SELECT 14 AS sample, 17327 AS pid, 9749020000000 AS start_ns, 9750691326083 AS end_ns UNION ALL SELECT 15 AS sample, 17327 AS pid, 9751610000000 AS start_ns, 9753281896292 AS end_ns UNION ALL SELECT 16 AS sample, 17327 AS pid, 9754080000000 AS start_ns, 9755743956834 AS end_ns UNION ALL SELECT 17 AS sample, 17327 AS pid, 9756650000000 AS start_ns, 9758310068374 AS end_ns UNION ALL SELECT 18 AS sample, 17327 AS pid, 9759130000000 AS start_ns, 9760812840084 AS end_ns UNION ALL SELECT 19 AS sample, 17327 AS pid, 9761860000000 AS start_ns, 9763516687542 AS end_ns UNION ALL SELECT 20 AS sample, 17327 AS pid, 9764460000000 AS start_ns, 9766110084209 AS end_ns UNION ALL SELECT 21 AS sample, 17327 AS pid, 9767200000000 AS start_ns, 9768905995791 AS end_ns UNION ALL SELECT 22 AS sample, 17327 AS pid, 9769820000000 AS start_ns, 9771484304708 AS end_ns UNION ALL SELECT 23 AS sample, 17327 AS pid, 9772290000000 AS start_ns, 9773939102333 AS end_ns UNION ALL SELECT 24 AS sample, 17327 AS pid, 9774860000000 AS start_ns, 9776507913625 AS end_ns UNION ALL SELECT 25 AS sample, 17327 AS pid, 9777370000000 AS start_ns, 9779054561084 AS end_ns UNION ALL SELECT 26 AS sample, 17327 AS pid, 9780150000000 AS start_ns, 9781804452084 AS end_ns UNION ALL SELECT 27 AS sample, 17327 AS pid, 9782700000000 AS start_ns, 9784403428291 AS end_ns UNION ALL SELECT 28 AS sample, 17327 AS pid, 9785330000000 AS start_ns, 9787008963999 AS end_ns UNION ALL SELECT 29 AS sample, 17327 AS pid, 9787890000000 AS start_ns, 9789586351416 AS end_ns UNION ALL SELECT 30 AS sample, 17327 AS pid, 9790450000000 AS start_ns, 9792143910250 AS end_ns UNION ALL SELECT 31 AS sample, 17327 AS pid, 9792990000000 AS start_ns, 9794671195208 AS end_ns UNION ALL SELECT 32 AS sample, 17327 AS pid, 9795530000000 AS start_ns, 9797201985499 AS end_ns UNION ALL SELECT 33 AS sample, 17327 AS pid, 9798080000000 AS start_ns, 9799742646833 AS end_ns UNION ALL SELECT 34 AS sample, 17327 AS pid, 9800500000000 AS start_ns, 9802170359665 AS end_ns UNION ALL SELECT 35 AS sample, 17327 AS pid, 9803080000000 AS start_ns, 9804727735084 AS end_ns)
SELECT w.sample, count(*) AS app_frame_records,
 sum(CASE WHEN a.jank_type LIKE '%App Deadline Missed%' THEN 1 ELSE 0 END) AS app_deadline_misses,
 sum(CASE WHEN a.jank_type != 'None' THEN 1 ELSE 0 END) AS all_jank_records,
 sum(CASE WHEN a.present_type = 'Dropped Frame' THEN 1 ELSE 0 END) AS dropped_frame_records,
 round(avg(a.dur)/1e6,2) AS mean_actual_frame_ms,
 round(max(a.dur)/1e6,2) AS max_actual_frame_ms,
 group_concat(a.dur) AS actual_durations_ns
FROM windows w JOIN process p ON p.pid=w.pid
JOIN actual_frame_timeline_slice a ON a.upid=p.upid
WHERE a.ts >= w.start_ns AND a.ts < w.end_ns AND a.dur > 0
GROUP BY w.sample ORDER BY w.sample